use dyst_source::{File, FileContent, FileId, FileType};

use crate::{
    JavaScriptFormatContext, JavaScriptFormatOptions, TranspileResult, Transpiler,
    TranspilerLanguage, TranspilerUnit, TranspilerUnitId,
};
use dyst_fir::format as fir_format;

/// An artifact generated by a TranspilerUnit.
#[derive(Debug, Clone)]
pub struct TranspilerArtifact {
    /// The id of the unit that generated this artifact.
    pub unit_id: TranspilerUnitId,
    /// The type of the artifact.
    pub ty: FileType,
    /// The file.
    pub file: File,
    /// The content of the artifact.
    pub content: FileContent,
}

impl<'a> Transpiler<'a> {
    /// Generate an artifact from a transpiled unit.
    pub fn generate_artifact(
        &self,
        unit: &TranspilerUnit,
        file_id: FileId,
        formatting: JavaScriptFormatOptions,
        language: TranspilerLanguage,
    ) -> TranspileResult<TranspilerArtifact> {
        // prepare file
        let ty = match language {
            TranspilerLanguage::JavaScript => FileType::JavaScript,
            TranspilerLanguage::TypeScript => FileType::TypeScript,
            TranspilerLanguage::TypeScriptDeclaration => FileType::TypeScriptDeclaration,
        };
        let extension = ty.extension().unwrap();
        let uri = unit.uri.with_extension(extension);
        let file = File::empty_text_with_id(ty, file_id, uri);

        // print unit
        let strings = unit.strings.clone().into_immutable(); // #Performance
        let context = JavaScriptFormatContext {
            options: formatting,
            file: &file,
            unit,
            tree: &unit.ast,
            strings: &strings,
        };
        // NOTE #Robustness: handle transpiler artifact print errors
        let formatted = fir_format!(context, [unit]).expect("failed to format");
        let printed = formatted.print().expect("failed to print");
        let content = printed.as_str().to_string();

        // make artifact
        let artifact = TranspilerArtifact {
            unit_id: unit.id,
            ty,
            file,
            content: FileContent::Text { content },
        };
        Ok(artifact)
    }
}
